From 76b20ddd856c31ca9e82d896f12410f731dd5b9c Mon Sep 17 00:00:00 2001
From: jbicker <jan.bicker@typefox.io>
Date: Wed, 3 Mar 2021 17:54:37 +0100
Subject: [PATCH] Show cookie settings by click on a respective button shown in
 footer

Fixes EclipseFdn/open-vsx.org#220
---
 website/src/footer-content.tsx | 29 ++++++++++++++++++++++++++++-
 1 file changed, 28 insertions(+), 1 deletion(-)

diff --git a/website/src/footer-content.tsx b/website/src/footer-content.tsx
index 6facf0706..72654be3a 100644
--- a/website/src/footer-content.tsx
+++ b/website/src/footer-content.tsx
@@ -31,13 +31,16 @@ const footerStyle = makeStyles((theme: Theme) => ({
     },
     legalText: {
         fontWeight: theme.typography.fontWeightLight
+    },
+    toolbarManageCookies: {
+        fontWeight: theme.typography.fontWeightLight
     }
 }));

 const FooterContent: React.FunctionComponent<{ expanded: boolean }> = ({ expanded }) => {
     const classes = footerStyle();
     const theme = useTheme();
-    const isSmallDisplay = useMediaQuery(theme.breakpoints.down('sm'));
+    const isSmallDisplay = useMediaQuery(theme.breakpoints.down('lg'));
     const isLargeDisplay = useMediaQuery(theme.breakpoints.up('xl'));

     const MainFooter = () => {
@@ -68,6 +71,9 @@ const FooterContent: React.FunctionComponent<{ expanded: boolean }> = ({ expande
                     <Box ml={itemSpacing}>
                         {rightsReservedText(classes)}
                     </Box>
+                    <Box ml={itemSpacing}>
+                        {manageCookies(classes)}
+                    </Box>
                 </Box>
                 :
                 <>
@@ -99,6 +105,9 @@ const FooterContent: React.FunctionComponent<{ expanded: boolean }> = ({ expande
                 <Box mb={itemSpacing + 1}>
                     {legalResources(classes)}
                 </Box>
+                <Box mb={itemSpacing + 1}>
+                    {manageCookies(classes)}
+                </Box>
             </Box>
             <MainFooter />
         </Box>;
@@ -166,4 +175,22 @@ const rightsReservedText = (classes: FooterStyle) =>
         All Rights Reserved.
     </Box>;

+const manageCookies = (classes: FooterStyle) => {
+    const handleClick = () => {
+        const ccWindow = document.getElementsByClassName('cc-window').item(0);
+        if(ccWindow) {
+            ccWindow.setAttribute('style', 'display:flex');
+            setTimeout(function() {
+              ccWindow.classList.remove('cc-invisible');
+            }, 20);
+        }
+    }
+    return <Link 
+        onClick={handleClick}
+        className={classes.link + ' ' + classes.toolbarManageCookies}>
+            Manage Cookies
+    </Link>;
+}
+
+
 export default FooterContent;
